const qs=(($input.first().json.body||{}).questions)||[];
if(!Array.isArray(qs)||qs.length===0){return [{json:{success:false,error:'Cevap verisi bos.'}}];}
let correct=0;const wrong=[];
for(const q of qs){if(q.user_answer===q.correct_answer){correct++;}else{wrong.push({question:q.question,topic:q.topic||'Genel',your_answer:q.user_answer,correct_answer:q.correct_answer});}}
const total=qs.length;const pct=Math.round(correct/total*100);
const topics=[...new Set(wrong.map(w=>w.topic))];
const stats={success:true,total,correct,wrong:total-correct,percentage:pct,weak_topics:topics,wrong_questions:wrong};
const info='Toplam: '+total+', Dogru: '+correct+', Yuzde: %'+pct+'. Yanlis yapilan konular: '+(topics.join(', ')||'yok')+'. Yanlis sorular: '+wrong.map(w=>w.question).join(' | ');
const sys='Sen bir universite egitim kocusun. Ogrencinin test sonucuna gore Turkce, kisa ve somut calisma onerileri ver. Once eksik konulari kisaca analiz et, sonra madde madde 3-5 calisma onerisi yaz.';
return [{json:{stats,ollamaBody:{model:'qwen2.5:7b',stream:false,messages:[{role:'system',content:sys},{role:'user',content:info}]}}}];

